class Solution {
public:
    int miceAndCheese(vector<int>& reward1, vector<int>& reward2, int k) {
        vector<int> diff;
        long long ans = 0;
        for (int i = 0; i < reward1.size(); i++) {
            diff.push_back(reward1[i] - reward2[i]);
            ans += reward2[i];
        }
        sort(diff.rbegin(), diff.rend());
        for (int i = 0; i < k; i++) ans += diff[i];
        return (int)ans;
    }
};

