import heapq
class Solution:
    def miceAndCheese(self, reward1: List[int], reward2: List[int], k: int) -> int:
        h = []
        for a, b in zip(reward1, reward2):
            heapq.heappush(h, a - b)
            if len(h) > k:
                heapq.heappop(h)
        return sum(reward2) + sum(h)

